extension Texts {
    // Quotations from Sun Tzu's The Art of War, cited by chapter (I–XIII).
    static let artOfWarEs = [
        Quote(text: "El arte de la guerra es de vital importancia para el Estado. Es una cuestión de vida o muerte, un camino hacia la seguridad o hacia la ruina.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Todo el arte de la guerra está basado en el engaño.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Cuando seas capaz de atacar, aparenta incapacidad; cuando uses tus fuerzas, aparenta inactividad.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Cuando estés cerca, haz creer al enemigo que estás lejos; cuando estés lejos, hazle creer que estás cerca.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Si tu oponente es de temperamento colérico, busca irritarlo. Finge ser débil para que se vuelva arrogante.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Atácalo donde no esté preparado; aparece donde no te espere.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "El general que gana una batalla hace muchos cálculos en su templo antes de que se libre el combate.", source: "Sun Tzu, El arte de la guerra, I"),
        Quote(text: "Nunca ha habido una guerra prolongada de la que un país se haya beneficiado.", source: "Sun Tzu, El arte de la guerra, II"),
        Quote(text: "En la guerra, pues, que tu gran objetivo sea la victoria, no las campañas prolongadas.", source: "Sun Tzu, El arte de la guerra, II"),
        Quote(text: "La suprema excelencia consiste en quebrar la resistencia del enemigo sin luchar.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "En el arte práctico de la guerra, lo mejor de todo es tomar intacto el país del enemigo; destrozarlo y destruirlo no es tan bueno.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "La peor política de todas es sitiar ciudades amuralladas.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "El líder hábil somete a las tropas del enemigo sin combate; captura sus ciudades sin sitiarlas y derroca su reino sin operaciones prolongadas.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "Gana quien sabe cuándo luchar y cuándo no luchar.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "Si conoces al enemigo y te conoces a ti mismo, no debes temer el resultado de cien batallas.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "Si te conoces a ti mismo pero no al enemigo, por cada victoria que ganes sufrirás también una derrota.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "Si no conoces ni al enemigo ni a ti mismo, sucumbirás en cada batalla.", source: "Sun Tzu, El arte de la guerra, III"),
        Quote(text: "Los antiguos guerreros expertos se ponían primero más allá de la posibilidad de la derrota y después esperaban la ocasión de derrotar al enemigo.", source: "Sun Tzu, El arte de la guerra, IV"),
        Quote(text: "Asegurarnos contra la derrota está en nuestras propias manos, pero la oportunidad de derrotar al enemigo la proporciona el propio enemigo.", source: "Sun Tzu, El arte de la guerra, IV"),
        Quote(text: "En la guerra, el estratega victorioso solo busca la batalla cuando la victoria ya se ha ganado, mientras que el destinado a la derrota primero lucha y después busca la victoria.", source: "Sun Tzu, El arte de la guerra, IV"),
        Quote(text: "En la batalla no hay más que dos métodos de ataque: el directo y el indirecto; pero estos dos, en combinación, dan lugar a una serie interminable de maniobras.", source: "Sun Tzu, El arte de la guerra, V"),
        Quote(text: "El desorden simulado presupone una disciplina perfecta; el miedo simulado requiere valor; la debilidad simulada exige fuerza.", source: "Sun Tzu, El arte de la guerra, V"),
        Quote(text: "El combatiente inteligente busca el efecto de la energía combinada y no exige demasiado de los individuos.", source: "Sun Tzu, El arte de la guerra, V"),
        Quote(text: "Quien llega primero al campo de batalla y espera la llegada del enemigo estará fresco para el combate; quien llega segundo y tiene que apresurarse a la batalla llegará agotado.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "Aparece en puntos que el enemigo se vea obligado a acudir a defender; marcha con rapidez hacia lugares donde no se te espere.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "¡Oh divino arte de la sutileza y el secreto! Gracias a ti aprendemos a ser invisibles e inaudibles, y así podemos tener en nuestras manos el destino del enemigo.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "Las tácticas militares son como el agua: en su curso natural huye de los lugares altos y se apresura hacia los bajos.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "Así como el agua no conserva una forma constante, en la guerra no existen condiciones permanentes.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "Quien sabe modificar su táctica según su adversario y logra así la victoria puede ser llamado un capitán nacido del cielo.", source: "Sun Tzu, El arte de la guerra, VI"),
        Quote(text: "Que tu rapidez sea como la del viento y tu compacidad como la del bosque. En el ataque y el saqueo sé como el fuego; en la firmeza, como la montaña.", source: "Sun Tzu, El arte de la guerra, VII"),
        Quote(text: "Que tus planes sean oscuros e impenetrables como la noche, y cuando te muevas, cae como un rayo.", source: "Sun Tzu, El arte de la guerra, VII"),
        Quote(text: "Pondera y delibera antes de hacer un movimiento.", source: "Sun Tzu, El arte de la guerra, VII"),
        Quote(text: "A un ejército rodeado debes dejarle una vía de salida; no presiones a un enemigo desesperado.", source: "Sun Tzu, El arte de la guerra, VII"),
        Quote(text: "El arte de la guerra nos enseña a no confiar en la probabilidad de que el enemigo no venga, sino en nuestra propia disposición para recibirlo.", source: "Sun Tzu, El arte de la guerra, VIII"),
        Quote(text: "La velocidad es la esencia misma de la guerra: aprovecha la falta de preparación del enemigo, avanza por rutas inesperadas y ataca los puntos desprotegidos.", source: "Sun Tzu, El arte de la guerra, XI"),
        Quote(text: "Este conocimiento previo no puede obtenerse de los espíritus, ni por inducción de la experiencia, ni por ningún cálculo deductivo. El conocimiento de las disposiciones del enemigo solo puede obtenerse de otros hombres.", source: "Sun Tzu, El arte de la guerra, XIII"),
    ]

    static let artOfWarEn = [
        Quote(text: "The art of war is of vital importance to the State. It is a matter of life and death, a road either to safety or to ruin.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "All warfare is based on deception.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "Hence, when able to attack, we must seem unable; when using our forces, we must seem inactive.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "When we are near, we must make the enemy believe we are far away; when far away, we must make him believe we are near.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "If your opponent is of choleric temper, seek to irritate him. Pretend to be weak, that he may grow arrogant.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "Attack him where he is unprepared, appear where you are not expected.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "The general who wins a battle makes many calculations in his temple ere the battle is fought.", source: "Sun Tzu, The Art of War, I (tr. Giles)"),
        Quote(text: "There is no instance of a country having benefited from prolonged warfare.", source: "Sun Tzu, The Art of War, II (tr. Giles)"),
        Quote(text: "In war, then, let your great object be victory, not lengthy campaigns.", source: "Sun Tzu, The Art of War, II (tr. Giles)"),
        Quote(text: "Supreme excellence consists in breaking the enemy's resistance without fighting.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "In the practical art of war, the best thing of all is to take the enemy's country whole and intact; to shatter and destroy it is not so good.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "The worst policy of all is to besiege walled cities.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "The skillful leader subdues the enemy's troops without any fighting; he captures their cities without laying siege to them; he overthrows their kingdom without lengthy operations in the field.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "He will win who knows when to fight and when not to fight.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "If you know the enemy and know yourself, you need not fear the result of a hundred battles.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "If you know yourself but not the enemy, for every victory gained you will also suffer a defeat.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "If you know neither the enemy nor yourself, you will succumb in every battle.", source: "Sun Tzu, The Art of War, III (tr. Giles)"),
        Quote(text: "The good fighters of old first put themselves beyond the possibility of defeat, and then waited for an opportunity of defeating the enemy.", source: "Sun Tzu, The Art of War, IV (tr. Giles)"),
        Quote(text: "To secure ourselves against defeat lies in our own hands, but the opportunity of defeating the enemy is provided by the enemy himself.", source: "Sun Tzu, The Art of War, IV (tr. Giles)"),
        Quote(text: "In war the victorious strategist only seeks battle after the victory has been won, whereas he who is destined to defeat first fights and afterwards looks for victory.", source: "Sun Tzu, The Art of War, IV (tr. Giles)"),
        Quote(text: "In battle, there are not more than two methods of attack: the direct and the indirect; yet these two in combination give rise to an endless series of maneuvers.", source: "Sun Tzu, The Art of War, V (tr. Giles)"),
        Quote(text: "Simulated disorder postulates perfect discipline; simulated fear postulates courage; simulated weakness postulates strength.", source: "Sun Tzu, The Art of War, V (tr. Giles)"),
        Quote(text: "The clever combatant looks to the effect of combined energy, and does not require too much from individuals.", source: "Sun Tzu, The Art of War, V (tr. Giles)"),
        Quote(text: "Whoever is first in the field and awaits the coming of the enemy, will be fresh for the fight; whoever is second in the field and has to hasten to battle will arrive exhausted.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "Appear at points which the enemy must hasten to defend; march swiftly to places where you are not expected.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "O divine art of subtlety and secrecy! Through you we learn to be invisible, through you inaudible; and hence we can hold the enemy's fate in our hands.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "Military tactics are like unto water; for water in its natural course runs away from high places and hastens downwards.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "Just as water retains no constant shape, so in warfare there are no constant conditions.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "He who can modify his tactics in relation to his opponent and thereby succeed in winning, may be called a heaven-born captain.", source: "Sun Tzu, The Art of War, VI (tr. Giles)"),
        Quote(text: "Let your rapidity be that of the wind, your compactness that of the forest. In raiding and plundering be like fire, in immovability like a mountain.", source: "Sun Tzu, The Art of War, VII (tr. Giles)"),
        Quote(text: "Let your plans be dark and impenetrable as night, and when you move, fall like a thunderbolt.", source: "Sun Tzu, The Art of War, VII (tr. Giles)"),
        Quote(text: "Ponder and deliberate before you make a move.", source: "Sun Tzu, The Art of War, VII (tr. Giles)"),
        Quote(text: "When you surround an army, leave an outlet free. Do not press a desperate foe too hard.", source: "Sun Tzu, The Art of War, VII (tr. Giles)"),
        Quote(text: "The art of war teaches us to rely not on the likelihood of the enemy's not coming, but on our own readiness to receive him.", source: "Sun Tzu, The Art of War, VIII (tr. Giles)"),
        Quote(text: "Rapidity is the essence of war: take advantage of the enemy's unreadiness, make your way by unexpected routes, and attack unguarded spots.", source: "Sun Tzu, The Art of War, XI (tr. Giles)"),
        Quote(text: "Foreknowledge cannot be elicited from spirits; it cannot be obtained inductively from experience, nor by any deductive calculation. Knowledge of the enemy's dispositions can only be obtained from other men.", source: "Sun Tzu, The Art of War, XIII (tr. Giles)"),
    ]
}
